#include <stdio.h>
#include <string.h>

#include "netdissect.h"
#include "netinet/ip6.h"

int
ipv6_print_routing_header(const struct netdissect_options *ndo, const u_char *bp, const u_char *bp2)
{
    const struct ip6_rthdr *rthdr = (const struct ip6_rthdr *)bp;
    int hdrlen = 0;

    if (rthdr->ip6r_len == 0)
        return -1;

    hdrlen = (rthdr->ip6r_len + 1) * 8;

    ND_PRINT("Routing Header: ");
    ND_PRINT("Length: %d, Type: %d, Segments Left: %d\n",
             rthdr->ip6r_len * 8, rthdr->ip6r_type, rthdr->ip6r_segleft);

    switch (rthdr->ip6r_type) {
        case 0: /* Type 0 - IPv6 Mobility Header */
            if (hdrlen < sizeof(struct ip6_rthdr)) {
                ND_PRINT("\tTruncated\n");
                return -1;
            }
            ND_PRINT("\tAddress: ");
            ND_PRINT("%s\n", ip6addr_string(ndo, &rthdr->ip6r_addr));
            break;
        default:
            ND_PRINT("\tUnknown Type\n");
            break;
    }

    return hdrlen;
}
